print(f"Degree: {degree}, Clique: {clique}, Chromatic: {chromatic}")

import itertools

def get_degree(n, edges):
    degrees = [0] * n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    return min(degrees)

def get_clique_number(n, edges):
    # Simple clique finder for small graphs
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    max_clique = 0
    for i in range(1, n + 1):
        for combo in itertools.combinations(range(n), i):
            is_clique = True
            for u, v in itertools.combinations(combo, 2):
                if v not in adj[u]:
                    is_clique = False
                    break
            if is_clique:
                max_clique = max(max_clique, i)
    return max_clique

def get_chromatic_number(n, edges):
    # Simple coloring
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Try coloring with k colors
    for k in range(1, n + 1):
        colors = [-1] * n
        if can_color(0, n, adj, colors, k):
            return k
    return n

def can_color(u, n, adj, colors, k):
    if u == n:
        return True

    for c in range(k):
        can_use = True
        for v in adj[u]:
            if colors[v] == c:
                can_use = False
                break
        if can_use:
            colors[u] = c
            if can_color(u + 1, n, adj, colors, k):
                return True
            colors[u] = -1
    return False

