n = 19
offsets = [1, 2, 3]
edges = []
for i in range(n):
    for offset in offsets:
        u = i
        v = (i + offset) % n
        if u < v:
            edges.append((u, v))
        elif v < u:
            edges.append((v, u))
edges = list(set(edges))

degree = get_degree(n, edges)
clique = get_clique_number(n, edges)
chromatic = get_chromatic_number(n, edges)

print(f"Degree: {degree}, Clique: {clique}, Chromatic: {chromatic}")
